//! Formation strength and claim proofs. Mirrors `schotten/rules.py` exactly;
//! `tests/parity.rs` checks that against fixtures generated by the Python code.

use super::cards::{self, Card, CardSet, bit};

/// (formation << 5) | total. Higher is stronger; formation order is
/// sum < run < color < three of a kind < color run, as in the Python `Formation`.
pub type Strength = u8;

pub const SUM: u8 = 0;
pub const RUN: u8 = 1;
pub const COLOR: u8 = 2;
pub const TRIPS: u8 = 3;
pub const COLOR_RUN: u8 = 4;

#[inline]
pub fn strength(formation: u8, total: u8) -> Strength {
    (formation << 5) | total
}

#[inline]
pub fn formation_of(s: Strength) -> u8 {
    s >> 5
}

pub fn formation_name(s: Strength) -> &'static str {
    ["sum", "run", "color", "trips", "color run"][formation_of(s) as usize]
}

/// Strength of a completed three-card formation.
#[inline]
pub fn evaluate(c: [Card; 3]) -> Strength {
    let (mut a, mut b, mut d) = (cards::value(c[0]), cards::value(c[1]), cards::value(c[2]));
    // sort three values
    if a > b {
        std::mem::swap(&mut a, &mut b);
    }
    if b > d {
        std::mem::swap(&mut b, &mut d);
    }
    if a > b {
        std::mem::swap(&mut a, &mut b);
    }
    let same_color =
        cards::color(c[0]) == cards::color(c[1]) && cards::color(c[1]) == cards::color(c[2]);
    let is_run = b == a + 1 && d == b + 1;
    let formation = if same_color && is_run {
        COLOR_RUN
    } else if a == d {
        TRIPS
    } else if same_color {
        COLOR
    } else if is_run {
        RUN
    } else {
        SUM
    };
    strength(formation, a + b + d)
}

/// The strongest formation an opponent could still complete, and one set of cards achieving it.
///
/// `partial` holds the 0-3 cards the opponent already has on the stone; `pool` is every card
/// they might still get. Returns None if the pool is too small to complete the stone.
/// Enumeration stops early once a completion of strength >= `stop_at` is found (the returned
/// strength is then only a lower bound on the maximum, which is all a claim check needs).
pub fn best_completion(
    partial: &[Card],
    pool: CardSet,
    stop_at: Strength,
) -> Option<(Strength, CardSet)> {
    let need = 3 - partial.len();
    if (pool.count_ones() as usize) < need {
        return None;
    }
    match partial.len() {
        3 => Some((evaluate([partial[0], partial[1], partial[2]]), 0)),
        2 => {
            let mut best = (0u8, 0u64);
            let mut found = false;
            for x in cards::iter(pool) {
                let s = evaluate([partial[0], partial[1], x]);
                if !found || s > best.0 {
                    best = (s, bit(x));
                    found = true;
                    if s >= stop_at {
                        break;
                    }
                }
            }
            Some(best)
        }
        1 => {
            let mut best = (0u8, 0u64);
            let mut found = false;
            let list: Vec<Card> = cards::iter(pool).collect();
            'outer: for i in 0..list.len() {
                for j in i + 1..list.len() {
                    let s = evaluate([partial[0], list[i], list[j]]);
                    if !found || s > best.0 {
                        best = (s, bit(list[i]) | bit(list[j]));
                        found = true;
                        if s >= stop_at {
                            break 'outer;
                        }
                    }
                }
            }
            Some(best)
        }
        _ => Some(best_triple(pool)),
    }
}

/// Strongest three-card formation inside `pool` (needs at least three cards), in closed form.
///
/// Works down the formation ladder: as soon as a formation exists in the pool, nothing weaker
/// can be the maximum, and every triple of a weaker kind is guaranteed not to be a stronger one.
fn best_triple(pool: CardSet) -> (Strength, CardSet) {
    // per-colour 9-bit masks of available values (bit v-1 set when value v is available)
    let mut by_color = [0u16; 6];
    for (c, m) in by_color.iter_mut().enumerate() {
        *m = ((pool >> (9 * c)) & 0x1FF) as u16;
    }
    let card_at = |c: usize, v0: usize| -> Card { (c * 9 + v0) as Card }; // v0 = value - 1

    // 1. colour run: highest start over all colours
    let mut best_run: Option<(usize, usize)> = None; // (start v0, colour)
    for (c, &m) in by_color.iter().enumerate() {
        for v0 in (0..=6).rev() {
            if (m >> v0) & 7 == 7 {
                if best_run.map_or(true, |(b, _)| v0 > b) {
                    best_run = Some((v0, c));
                }
                break;
            }
        }
    }
    if let Some((v0, c)) = best_run {
        let w = bit(card_at(c, v0)) | bit(card_at(c, v0 + 1)) | bit(card_at(c, v0 + 2));
        return (strength(COLOR_RUN, (3 * v0 + 6) as u8), w);
    }

    // 2. three of a kind: highest value with three colours available
    for v0 in (0..9).rev() {
        let cols: Vec<usize> = (0..6).filter(|&c| (by_color[c] >> v0) & 1 == 1).collect();
        if cols.len() >= 3 {
            let w =
                bit(card_at(cols[0], v0)) | bit(card_at(cols[1], v0)) | bit(card_at(cols[2], v0));
            return (strength(TRIPS, (3 * (v0 + 1)) as u8), w);
        }
    }

    // 3. colour (three of one colour, no run exists): best is that colour's top three
    let mut best_col: Option<(u8, CardSet)> = None;
    for (c, &m) in by_color.iter().enumerate() {
        if m.count_ones() >= 3 {
            let mut sum = 0u8;
            let mut w = 0u64;
            let mut taken = 0;
            for v0 in (0..9).rev() {
                if (m >> v0) & 1 == 1 && taken < 3 {
                    sum += (v0 + 1) as u8;
                    w |= bit(card_at(c, v0));
                    taken += 1;
                }
            }
            if best_col.map_or(true, |(s, _)| sum > s) {
                best_col = Some((sum, w));
            }
        }
    }
    if let Some((sum, w)) = best_col {
        return (strength(COLOR, sum), w);
    }

    // 4. run: three consecutive values from any colours (no colour run exists, so never one)
    let any: Vec<Option<usize>> = (0..9)
        .map(|v0| (0..6).find(|&c| (by_color[c] >> v0) & 1 == 1))
        .collect();
    for v0 in (0..=6).rev() {
        if let (Some(a), Some(b), Some(d)) = (any[v0], any[v0 + 1], any[v0 + 2]) {
            let w = bit(card_at(a, v0)) | bit(card_at(b, v0 + 1)) | bit(card_at(d, v0 + 2));
            return (strength(RUN, (3 * v0 + 6) as u8), w);
        }
    }

    // 5. sum: the three highest cards
    let mut sum = 0u8;
    let mut w = 0u64;
    let mut taken = 0;
    for v0 in (0..9).rev() {
        for c in 0..6 {
            if (by_color[c] >> v0) & 1 == 1 && taken < 3 {
                sum += (v0 + 1) as u8;
                w |= bit(card_at(c, v0));
                taken += 1;
            }
        }
    }
    (strength(SUM, sum), w)
}

/// Outcome of asking "can this claim be proven?".
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Proof {
    Provable,
    /// Not provable. The mask is a set of pool cards that would beat (or, without the
    /// tiebreak, tie) the claim; the answer stays "blocked" while all of them remain in the
    /// pool. A mask of 0 means the stone is settled against the claimer.
    Blocked(CardSet),
}

/// Can the owner of `mine` (three cards) prove the opponent cannot win this stone?
///
/// `theirs` holds the opponent's 0-3 cards, `pool` every card they could still get, and
/// `tiebreak_mine` says an exact tie goes to the claimer (they completed first).
pub fn check_claim(mine: [Card; 3], theirs: &[Card], pool: CardSet, tiebreak_mine: bool) -> Proof {
    let mine_strength = evaluate(mine);
    // The opponent blocks the claim with any completion at least this strong.
    let need = if tiebreak_mine {
        mine_strength.saturating_add(1)
    } else {
        mine_strength
    };
    match best_completion(theirs, pool, need) {
        None => Proof::Provable, // they can never complete the stone
        Some((s, witness)) => {
            if s >= need {
                Proof::Blocked(witness)
            } else {
                Proof::Provable
            }
        }
    }
}
